            writeInt(&buf, Int32(2))
            FfiConverterString.write(color, into: &buf)
            
        
        case let .blur(blur):
            writeInt(&buf, Int32(3))
            FfiConverterDouble.write(blur, into: &buf)
            
        }
    }
}


